// LucaT: Analizzatore delle variabili di ambiente per InfluxDB

// Funzione helper per ottenere variabile di ambiente o undefined
function getEnvVar(varName) {
    try {
        return env.get(varName);
    } catch (e) {
        return undefined;
    }
}

// Variabili di base sempre controllate
const baseVars = {
    IDB_ENABLED: getEnvVar('IDB_ENABLED'),
    IDB_VERSION: getEnvVar('IDB_VERSION')
};

// Determina la versione da analizzare
let version = baseVars.IDB_VERSION;
if (!version) {
    version = '1'; // Default version
}

// Normalizza la versione
let normalizedVersion;
switch(version) {
    case '1':
    case '1.x':
        normalizedVersion = '1.x';
        break;
    case '1.8':
    case '1.8-flux':
        normalizedVersion = '1.8-flux';
        break;
    case '2':
    case '2.0':
        normalizedVersion = '2.0';
        break;
    default:
        normalizedVersion = 'unknown';
}

// Variabili specifiche per versione
const versionSpecificVars = {};

if (normalizedVersion === '1.x') {
    // Variabili per InfluxDB 1.x
    versionSpecificVars.connection = {
        IDB_HOSTNAME: getEnvVar('IDB_HOSTNAME'),
        IDB_PORT: getEnvVar('IDB_PORT'),
        IDB_DATABASE: getEnvVar('IDB_DATABASE'),
        IDB_USERNAME: getEnvVar('IDB_USERNAME'),
        IDB_PASSWORD: getEnvVar('IDB_PASSWORD') ? '***MASKED***' : undefined
    };

    versionSpecificVars.nodes = {
        // OUT node
        IDB_MEASUREMENT_OUT: getEnvVar('IDB_MEASUREMENT_OUT'),
        IDB_PRECISION_OUT: getEnvVar('IDB_PRECISION_OUT'),
        IDB_RETENTION_POLICY_OUT: getEnvVar('IDB_RETENTION_POLICY_OUT'),

        // BATCH node
        IDB_PRECISION_BATCH: getEnvVar('IDB_PRECISION_BATCH'),
        IDB_RETENTION_POLICY_BATCH: getEnvVar('IDB_RETENTION_POLICY_BATCH'),

        // IN node
        IDB_QUERY_IN: getEnvVar('IDB_QUERY_IN'),
        IDB_RAW_OUTPUT_IN: getEnvVar('IDB_RAW_OUTPUT_IN'),
        IDB_PRECISION_IN: getEnvVar('IDB_PRECISION_IN'),
        IDB_RETENTION_POLICY_IN: getEnvVar('IDB_RETENTION_POLICY_IN')
    };

} else if (normalizedVersion === '1.8-flux') {
    // Variabili per InfluxDB 1.8-Flux
    versionSpecificVars.connection = {
        IDB_URL: getEnvVar('IDB_URL'),
        IDB_USERNAME: getEnvVar('IDB_USERNAME'),
        IDB_PASSWORD: getEnvVar('IDB_PASSWORD') ? '***MASKED***' : undefined
    };

    versionSpecificVars.nodes = {
        // OUT node
        IDB_MEASUREMENT_OUT: getEnvVar('IDB_MEASUREMENT_OUT'),
        IDB_PRECISION_OUT: getEnvVar('IDB_PRECISION_OUT'),
        IDB_DATABASE_OUT: getEnvVar('IDB_DATABASE_OUT'),
        IDB_RETENTION_POLICY_OUT: getEnvVar('IDB_RETENTION_POLICY_OUT'),

        // BATCH node
        IDB_PRECISION_BATCH: getEnvVar('IDB_PRECISION_BATCH'),
        IDB_DATABASE_BATCH: getEnvVar('IDB_DATABASE_BATCH'),
        IDB_RETENTION_POLICY_BATCH: getEnvVar('IDB_RETENTION_POLICY_BATCH'),

        // IN node
        IDB_QUERY_IN: getEnvVar('IDB_QUERY_IN'),
        IDB_ORGANIZATION_IN: getEnvVar('IDB_ORGANIZATION_IN')
    };

} else if (normalizedVersion === '2.0') {
    // Variabili per InfluxDB 2.0
    versionSpecificVars.connection = {
        IDB_URL: getEnvVar('IDB_URL'),
        IDB_TOKEN: getEnvVar('IDB_TOKEN') ? '***MASKED***' : undefined,
        IDB_TIMEOUT: getEnvVar('IDB_TIMEOUT'),
        IDB_VERIFY_CERTIFICATE: getEnvVar('IDB_VERIFY_CERTIFICATE')
    };

    versionSpecificVars.nodes = {
        // OUT node
        IDB_MEASUREMENT_OUT: getEnvVar('IDB_MEASUREMENT_OUT'),
        IDB_PRECISION_OUT: getEnvVar('IDB_PRECISION_OUT'),
        IDB_ORGANIZATION_OUT: getEnvVar('IDB_ORGANIZATION_OUT'),
        IDB_BUCKET_OUT: getEnvVar('IDB_BUCKET_OUT'),

        // BATCH node
        IDB_PRECISION_BATCH: getEnvVar('IDB_PRECISION_BATCH'),
        IDB_ORGANIZATION_BATCH: getEnvVar('IDB_ORGANIZATION_BATCH'),
        IDB_BUCKET_BATCH: getEnvVar('IDB_BUCKET_BATCH'),

        // IN node
        IDB_QUERY_IN: getEnvVar('IDB_QUERY_IN'),
        IDB_ORGANIZATION_IN: getEnvVar('IDB_ORGANIZATION_IN')
    };
}

// Funzione per contare variabili definite
function countDefinedVars(obj) {
    let count = 0;
    for (let key in obj) {
        if (typeof obj[key] === 'object') {
            count += countDefinedVars(obj[key]);
        } else if (obj[key] !== undefined) {
            count++;
        }
    }
    return count;
}

// Funzione per rimuovere variabili undefined dall'output
function removeUndefined(obj) {
    const result = {};
    for (let key in obj) {
        if (typeof obj[key] === 'object' && obj[key] !== null) {
            const cleaned = removeUndefined(obj[key]);
            if (Object.keys(cleaned).length > 0) {
                result[key] = cleaned;
            }
        } else if (obj[key] !== undefined) {
            result[key] = obj[key];
        }
    }
    return result;
}

// Crea il risultato finale
const result = {
    timestamp: new Date().toISOString(),
    analysis: {
        base_variables: baseVars,
        detected_version: {
            raw: version,
            normalized: normalizedVersion,
            is_valid: normalizedVersion !== 'unknown'
        },
        connection_enabled: {
            raw_value: baseVars.IDB_ENABLED,
            interpreted: !baseVars.IDB_ENABLED || 
                        (baseVars.IDB_ENABLED.toLowerCase() !== 'false' && 
                         baseVars.IDB_ENABLED !== '0'),
            note: "Empty or missing = enabled, 'false'/'0' = disabled"
        }
    },
    environment_variables: {
        version_specific: removeUndefined(versionSpecificVars),
        statistics: {
            total_variables_defined: countDefinedVars(versionSpecificVars),
            connection_vars_defined: countDefinedVars(versionSpecificVars.connection || {}),
            node_vars_defined: countDefinedVars(versionSpecificVars.nodes || {})
        }
    },
    recommendations: []
};

// Aggiungi raccomandazioni
if (!baseVars.IDB_ENABLED) {
    result.recommendations.push("Consider setting IDB_ENABLED to control connection behavior");
}

if (!baseVars.IDB_VERSION) {
    result.recommendations.push("IDB_VERSION not set - defaulting to 1.x");
} else if (normalizedVersion === 'unknown') {
    result.recommendations.push("Invalid IDB_VERSION '" + version + "' - use '1', '1.8', or '2'");
}

if (normalizedVersion !== 'unknown') {
    const connectionVars = versionSpecificVars.connection || {};
    const hasConnectionVars = Object.values(connectionVars).some(v => v !== undefined && v !== '***MASKED***');

    if (!hasConnectionVars) {
        result.recommendations.push(`No connection variables found for ${normalizedVersion}`);
    }

    const nodeVars = versionSpecificVars.nodes || {};
    const hasNodeVars = Object.values(nodeVars).some(v => v !== undefined);

    if (!hasNodeVars) {
        result.recommendations.push(`No node-specific variables found for ${normalizedVersion}`);
    }
}

// Output del risultato
msg.payload = result;
msg.topic = "influxdb_env_analysis";
msg.version = normalizedVersion;
msg.enabled = result.analysis.connection_enabled.interpreted;

return msg;
